// HasMember applies the HasEdge predicate on the "member" edge.
func HasMember() predicate.MemberPeriodStats {
	return predicate.MemberPeriodStats(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, MemberTable, MemberColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasMemberWith applies the HasEdge predicate on the "member" edge with a given conditions (other predicates).
func HasMemberWith(preds ...predicate.Member) predicate.MemberPeriodStats {
	return predicate.MemberPeriodStats(func(s *sql.Selector) {
		step := newMemberStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MemberPeriodStats) predicate.MemberPeriodStats {
	return predicate.MemberPeriodStats(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MemberPeriodStats) predicate.MemberPeriodStats {
	return predicate.MemberPeriodStats(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MemberPeriodStats) predicate.MemberPeriodStats {
	return predicate.MemberPeriodStats(sql.NotPredicates(p))
}
